import {expect,test}from"@playwright/test";
const a=["/models/drums/components/bass-toms.glb","/models/drums/components/snare-stand.glb","/models/drums/components/floor-tom.glb","/models/drums/components/hihat-stand.glb","/models/drums/components/crash-stand.glb","/models/drums/hands/left-hold.glb","/models/drums/hands/right-hold.glb"];
async function ready(p:any){await expect(p.locator(".drum-kit-canvas")).toHaveAttribute("data-engine-status","ready");await expect.poll(()=>p.evaluate((x:string[])=>performance.getEntriesByType("resource").filter((e:any)=>x.some(u=>e.name.includes(u))).length,a)).toBe(7);await p.waitForTimeout(250)}
async function m(p:any){return p.locator(".drum-kit-canvas").evaluate((h:any)=>{const c=h.querySelector("canvas"),r=h.getBoundingClientRect(),q=c.getBoundingClientRect();return{host:[r.width,r.height],canvas:[c.width,c.height,q.width,q.height],model:h.dataset.modelVersion,view:h.dataset.view,calls:+h.dataset.drawCalls,tris:+h.dataset.triangles,static:+h.dataset.staticObjectCount}})}
test("v29 component GLB runtime",async({page,browser})=>{const problems:string[]=[];page.on("console",x=>{if(["error","warning"].includes(x.type())&&!x.text().includes("GL Driver Message"))problems.push(x.text())});page.on("requestfailed",x=>problems.push(x.url()));await page.setViewportSize({width:807,height:361});await page.goto("/kit");await ready(page);console.log("KIT",JSON.stringify(await m(page)));const kc=page.locator("canvas");await kc.screenshot({path:"output/playwright/drum-model-qa-licensed-v3-final/runtime/kit-loaded.png"});await kc.focus();for(const key of ["Space","f","j","k","l"])await page.keyboard.press(key);for(const p of [{x:243,y:255},{x:184,y:224},{x:138,y:126},{x:250,y:175},{x:365,y:91}])await kc.click({position:p,force:true});expect(problems).toEqual([]);await page.setViewportSize({width:844,height:340});await page.goto("/practice");await ready(page);console.log("PRACTICE",JSON.stringify(await m(page)));const pc=page.locator("canvas");await pc.screenshot({path:"output/playwright/drum-model-qa-licensed-v3-final/runtime/practice-idle.png"});await page.getByRole("button",{name:"Start 4-count"}).click();await expect(page.locator(".mode-pill")).toHaveText("count-in");await page.evaluate(()=>window.advanceTime?.(4200));await expect(page.locator(".mode-pill")).toHaveText("playing");await page.keyboard.press("f");await page.waitForTimeout(95);await pc.screenshot({path:"output/playwright/drum-model-qa-licensed-v3-final/runtime/snare-contact-95ms.png"});await page.waitForTimeout(50);await pc.screenshot({path:"output/playwright/drum-model-qa-licensed-v3-final/runtime/snare-rebound-145ms.png"});await page.goto("/trainer");await ready(page);console.log("TRAINER",JSON.stringify(await m(page)));await page.locator("canvas").screenshot({path:"output/playwright/drum-model-qa-licensed-v3-final/runtime/trainer.png"});expect(await page.locator("canvas").count()).toBe(1);const ctx=await browser.newContext();const f=await ctx.newPage();let fb=false;f.on("console",x=>{if(x.text().includes("licensed model load failed; keeping procedural fallback"))fb=true});await f.route("**/models/drums/**/*.glb",x=>x.abort("failed"));await f.goto("/kit");await expect(f.locator(".drum-kit-canvas")).toHaveAttribute("data-engine-status","ready");await expect.poll(()=>fb).toBe(true);await ctx.close()});
